/** The frames of the summary stream: `event: <event>` and `data: <JSON of data>`. */
export type SummaryStreamEvent =
  | { event: 'meta'; data: { message_count: number; window: SummaryWindowKey; from_at: string; to_at: string } }
  | { event: 'delta'; data: { delta: string } }
  | { event: 'done'; data: { cached: boolean; summary: SummaryDto } }
  | { event: 'error'; data: { code: 'invalid_api_key' | 'generation_failed'; message: string } };

